mapper.select:
SELECT

FROM `record`
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

mapper.delete:
DELETE FROM `record`
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

mapper.update:
UPDATE `record`
SET
    status = 'SEALED',
    sealed_at = #{sealedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

UPDATE `record`
SET
    reality_later = #{realityLater},
    reality_later_submit_count = COALESCE(reality_later_submit_count, 0) + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'UNLOCKED'
  AND COALESCE(reality_later_submit_count, 0) < 2

UPDATE `record`
SET
    cover_attachment_id = #{coverAttachmentId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

UPDATE `record`
SET
    content = #{content},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

UPDATE `record`
SET
    unlock_at = #{unlockAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

UPDATE `record`
SET
    cover_attachment_id = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND cover_attachment_id = #{coverAttachmentId}

mapper.select:
SELECT COUNT(1)
FROM `record` r
WHERE r.user_id = #{userId}

    AND r.status = #{status}


    AND r.record_type = #{recordType}


    AND EXISTS (
        SELECT 1
        FROM record_tag rt
        WHERE rt.record_id = r.id
          AND rt.tag_id = #{tagId}
    )


    AND (
        r.title LIKE CONCAT('%', #{keyword}, '%')
        OR r.content LIKE CONCAT('%', #{keyword}, '%')
    )

SELECT

FROM `record` r
WHERE r.user_id = #{userId}

    AND r.status = #{status}


    AND r.record_type = #{recordType}


    AND EXISTS (
        SELECT 1
        FROM record_tag rt
        WHERE rt.record_id = r.id
          AND rt.tag_id = #{tagId}
    )


    AND (
        r.title LIKE CONCAT('%', #{keyword}, '%')
        OR r.content LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY r.created_at DESC, r.id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT

FROM `record`
WHERE user_id = #{userId}
  AND status = 'UNLOCKED'
ORDER BY unlocked_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.sql:
WHERE r.user_id = #{userId}

    AND r.created_at >= #{createdFrom}


    AND r.created_at < #{createdBefore}


    AND EXISTS (
        SELECT 1
        FROM record_tag rt
        INNER JOIN tag t
            ON t.id = rt.tag_id
           AND t.status = 'ENABLED'
        WHERE rt.record_id = r.id
          AND rt.tag_id = #{tagId}
    )

mapper.select:
SELECT
FROM `record` r
ORDER BY r.created_at DESC, r.id DESC LIMIT #{pageSize} OFFSET #{offset}
